insert into public.drills (id, dir, topic, sort, context, source, for_author, focus) values
('dr-20260929-ke-m1','KR→EN','marketing',1,'비건 베이커리 신메뉴 포스터','버터 없이도 바삭해요. 한 입이면 믿게 될 거예요.',null,''),
('dr-20260929-ke-m2','KR→EN','marketing',2,'중고 거래 앱 푸시 알림','옷장 속 안 입는 옷, 누군가에겐 올해의 인생템이에요.',null,''),
('dr-20260929-ke-m3','KR→EN','marketing',3,'호텔 조식 안내 SNS','아침은 천천히. 조식은 11시까지 준비돼 있어요.',null,''),
('dr-20260929-ke-b1','KR→EN','business',1,'고객과의 통화 일정 변경','갑작스러운 일이 생겨 오늘 오후 통화를 내일로 옮길 수 있을까요? 번거롭게 해 드려 죄송합니다.',(select email from public.members where display_name='희주'),'사정은 personal 대신 something has come up'),
('dr-20260929-ke-b2','KR→EN','business',2,'회의 후 수정안 안내 메일','오늘 논의한 내용을 바탕으로 수정안을 만들어 금요일까지 보내 드리겠습니다.',null,''),
('dr-20260929-ke-b3','KR→EN','business',3,'지원자에게 불합격 안내','아쉽게도 이번에는 함께하지 못하게 되었습니다. 보내 주신 관심에 깊이 감사드립니다.',null,''),
('dr-20260929-ke-d1','KR→EN','daily',1,'친구에게 전시회 제안','다음에 같이 전시회 보러 가자. 표는 내가 예매할게.',(select email from public.members where display_name='혜림'),'''~하자''는 Let''s, 명사 하나엔 a/an'),
('dr-20260929-ke-d2','KR→EN','daily',2,'외출하는 가족에게','내일 눈 온대. 따뜻하게 입고 나가.',(select email from public.members where display_name='혜림'),'들은 예보는 be supposed to'),
('dr-20260929-ke-d3','KR→EN','daily',3,'친구가 이사했다고 할 때','이사했다며? 집들이 언제 해?',null,''),
('dr-20260929-ke-t1','KR→EN','travel',1,'여행지 약국에서','두통약 있나요? 하루에 몇 번 먹으면 되나요?',(select email from public.members where display_name='혜림'),'관사 a/an과 셀 수 있는 명사'),
('dr-20260929-ke-t2','KR→EN','travel',2,'공항 체크인 카운터','창가 자리로 바꿀 수 있을까요? 짐은 하나만 부칠게요.',null,''),
('dr-20260929-ke-t3','KR→EN','travel',3,'렌터카 대여 창구','보험은 전부 포함된 걸로 해 주세요. 반납은 공항 지점에서 할게요.',null,''),
('dr-20260929-ek-m1','EN→KR','marketing',1,'무선 이어폰 광고','Your commute just got quieter.',(select email from public.members where display_name='희주'),'''당신의''는 빼고 짧게'),
('dr-20260929-ek-m2','EN→KR','marketing',2,'커피 원두 구독 이메일 제목','Fresh beans, right on schedule.',null,''),
('dr-20260929-ek-m3','EN→KR','marketing',3,'요가 스튜디오 SNS','Stretch more. Stress less.',null,''),
('dr-20260929-ek-b1','EN→KR','business',1,'동료에게 검토 부탁','Would you mind taking a quick look at this before I send it out?',null,''),
('dr-20260929-ek-b2','EN→KR','business',2,'프로젝트 일정 공유','We''re on track to launch by the end of the month.',null,''),
('dr-20260929-ek-b3','EN→KR','business',3,'협력사에 감사 인사','We couldn''t have asked for a better partner.',null,''),
('dr-20260929-ek-d1','EN→KR','daily',1,'친구의 고민을 듣고','I''ve been there. It gets easier, I promise.',null,''),
('dr-20260929-ek-d2','EN→KR','daily',2,'늦는 친구에게 문자','No rush. I just grabbed a coffee.',null,''),
('dr-20260929-ek-d3','EN→KR','daily',3,'친구가 칭찬할 때','Stop, you''re making me blush.',null,''),
('dr-20260929-ek-t1','EN→KR','travel',1,'공항 탑승구 안내 방송','This is the final boarding call for flight 902 to Sydney.',null,''),
('dr-20260929-ek-t2','EN→KR','travel',2,'호텔 체크아웃 때 직원','Would you like us to hold your luggage until your flight?',null,''),
('dr-20260929-ek-t3','EN→KR','travel',3,'여행지 식당 직원','The kitchen closes in twenty minutes, just so you know.',null,'');
insert into public.drill_models (drill_id, best, alternatives, notes) values
('dr-20260929-ke-m1','Flaky without the butter. One bite and you''ll believe it.','["All the crunch, none of the butter. Take a bite and see.", "No butter, still flaky. One bite will convince you."]'::jsonb,'[{"phrase": "버터 없이도 → without the butter", "why": "''even without butter''보다 카피에서는 without the ~로 짧게 대비시켜요."}, {"phrase": "믿게 될 거예요 → you''ll believe it", "why": "수동형(be made to believe)으로 옮기지 않아요. 짧은 미래형이 자신 있게 들려요."}]'::jsonb),
('dr-20260929-ke-m2','The clothes you never wear could be someone else''s favorite find this year.','["What''s gathering dust in your closet could be someone''s best buy of the year.", "Your closet''s forgotten pieces are someone else''s next favorite."]'::jsonb,'[{"phrase": "인생템 → favorite find", "why": "직역하면 ''life item''이라 어색해요. 영어는 favorite find 같은 말을 써요."}, {"phrase": "안 입는 옷 → clothes you never wear", "why": "''not wearing clothes''는 ''옷을 안 입은''으로 오해돼요. 관계절로 풀어요."}]'::jsonb),
('dr-20260929-ke-m3','Take your time this morning. Breakfast is served until 11.','["No rush. Breakfast runs until 11.", "Slow mornings welcome. Breakfast is on until 11 a.m."]'::jsonb,'[{"phrase": "아침은 천천히 → Take your time", "why": "명사로 끝나는 카피를 ''Morning is slow''로 옮기면 뜻이 달라져요. 권하는 동사로 바꿔요."}, {"phrase": "준비돼 있어요 → is served until", "why": "식사 시간 안내는 is prepared보다 is served, runs예요."}]'::jsonb),
('dr-20260929-ke-b1','Something has come up unexpectedly. Would it be possible to move this afternoon''s call to tomorrow? Sorry for the inconvenience.','["Due to an unforeseen conflict, could we reschedule today''s call to tomorrow? Apologies for any inconvenience.", "I''m afraid something urgent has come up. Could we push this afternoon''s call to tomorrow? Sorry for the trouble."]'::jsonb,'[{"phrase": "갑작스러운 일이 생겨 → Something has come up", "why": "personal commitments처럼 이유를 드러내면 상대보다 내 일정을 앞세우는 인상을 줘요. 이유 없이 사정을 알리는 정형 표현이에요."}, {"phrase": "옮기다 → move / reschedule / push", "why": "postpone도 맞아요. push는 조금 더 구어적이에요."}, {"phrase": "번거롭게 해 드려 죄송합니다 → Sorry for the inconvenience", "why": "일정 변경 사과의 정형 표현이에요."}]'::jsonb),
('dr-20260929-ke-b2','Based on today''s discussion, I''ll put together a revised draft and send it over by Friday.','["I''ll revise the draft to reflect what we discussed today and share it by Friday.", "Following today''s meeting, I''ll send you an updated proposal by Friday."]'::jsonb,'[{"phrase": "~을 바탕으로 → Based on", "why": "메일에서는 On the basis of보다 Based on이 짧고 자연스러워요."}, {"phrase": "만들어 → put together", "why": "make a revised plan은 딱딱해요. 자료를 정리해 만든다는 put together가 자연스러워요."}, {"phrase": "보내 드리겠습니다 → send it over", "why": "''드리다''의 공손함은 문장 전체 톤으로 전해요."}]'::jsonb),
('dr-20260929-ke-b3','Unfortunately, we won''t be moving forward with your application this time. Thank you sincerely for your interest.','["We regret to inform you that we''ve decided not to proceed with your application at this time. We truly appreciate your interest.", "We''re sorry to say we won''t be able to offer you a position this time. Thank you for your interest in joining us."]'::jsonb,'[{"phrase": "함께하지 못하게 되었습니다 → won''t be moving forward", "why": "''We cannot be together''는 연애처럼 들려요. 채용 결과는 move forward, proceed with를 써요."}, {"phrase": "보내 주신 관심 → your interest", "why": "''the interest you sent''가 아니에요. 소유격 your 하나로 충분해요."}]'::jsonb),
('dr-20260929-ke-d1','Let''s go see an exhibition together sometime. I''ll book the tickets.','["We should check out an exhibition sometime. I''ll get the tickets.", "Let''s catch an exhibit together next time. I''ll handle the tickets."]'::jsonb,'[{"phrase": "~하자 → Let''s", "why": "We have to go는 의무처럼 들려요. 제안은 Let''s, We should예요."}, {"phrase": "전시회 → an exhibition", "why": "셀 수 있는 명사 하나에는 a/an이 필요해요. exhibition은 모음 소리로 시작해서 an이에요."}, {"phrase": "예매할게 → I''ll book", "why": "reserve도 되지만 표는 book, get을 가장 많이 써요."}]'::jsonb),
('dr-20260929-ke-d2','It''s supposed to snow tomorrow. Bundle up before you head out.','["They say it''s going to snow tomorrow, so dress warmly.", "Snow''s in the forecast for tomorrow. Make sure you wear something warm."]'::jsonb,'[{"phrase": "눈 온대 → It''s supposed to snow", "why": "들은 소식은 be supposed to, They say로 옮겨요. It''s snowing tomorrow는 확정된 계획처럼 들려요."}, {"phrase": "따뜻하게 입어 → Bundle up / dress warmly", "why": "wear warmly는 어색해요. bundle up은 가족·친구 사이에 딱 맞는 구어예요."}]'::jsonb),
('dr-20260929-ke-d3','I heard you moved! When''s the housewarming?','["You moved? When are you throwing a housewarming party?", "So you''ve moved! When do we get to see the new place?"]'::jsonb,'[{"phrase": "~했다며? → I heard you ...", "why": "들은 이야기를 확인하는 ''~했다며''는 I heard, So you''ve ~로 옮겨요."}, {"phrase": "집들이 → housewarming (party)", "why": "같은 개념의 단어가 있어요. throw a housewarming party처럼 throw와 함께 써요."}]'::jsonb),
('dr-20260929-ke-t1','Do you have something for a headache? How many times a day should I take it?','["Do you have any headache medicine? How often should I take it?", "I need something for a headache. How many times a day do I take this?"]'::jsonb,'[{"phrase": "두통약 → something for a headache", "why": "약국에서는 something for a headache가 가장 자연스러워요. a headache의 a를 빼먹지 않아요."}, {"phrase": "하루에 몇 번 → How many times a day", "why": "a day의 a가 ''하루에''예요."}, {"phrase": "먹다 → take", "why": "약은 eat이 아니라 take예요."}]'::jsonb),
('dr-20260929-ke-t2','Could I switch to a window seat? I''ll just be checking one bag.','["Is it possible to change to a window seat? I only have one bag to check.", "Any chance I could get a window seat instead? Just one checked bag for me."]'::jsonb,'[{"phrase": "짐을 부치다 → check a bag", "why": "''send luggage''가 아니에요. 공항에서 짐을 맡기는 건 check예요."}, {"phrase": "바꿀 수 있을까요 → Could I switch to", "why": "change my seat to도 돼요. switch는 좀 더 가볍게 들려요."}]'::jsonb),
('dr-20260929-ke-t3','I''d like full coverage, please. I''ll be returning the car at the airport location.','["Please include full insurance coverage. I''ll drop the car off at the airport branch.", "Could I get the full coverage option? I''m returning it at the airport."]'::jsonb,'[{"phrase": "보험 전부 포함 → full coverage", "why": "렌터카 보험은 insurance보다 coverage라고 자주 말해요."}, {"phrase": "반납하다 → return / drop off", "why": "drop off는 차를 두고 간다는 느낌의 구어예요."}, {"phrase": "지점 → location / branch", "why": "렌터카·은행 지점은 location, branch예요."}]'::jsonb),
('dr-20260929-ek-m1','출근길이 한결 조용해졌어요.','["지하철이 조용해지는 순간.", "매일의 출근길, 이제 조용하게."]'::jsonb,'[{"phrase": "Your → 생략", "why": "''당신의 통근길''은 거리감이 들고 번역투예요. 한국어 광고는 소유격을 빼도 통해요."}, {"phrase": "just got quieter → 한결 조용해졌어요", "why": "''방금 더 조용해졌다''가 아니에요. just got + 비교급은 ''이제 ~해졌다''는 변화예요."}, {"phrase": "commute → 출근길", "why": "''통근''보다 ''출근길''이 생활감 있는 말이에요."}]'::jsonb),
('dr-20260929-ek-m2','갓 볶은 원두, 약속한 날에 딱 맞춰.','["신선한 원두가 제때 도착해요.", "원두는 신선하게, 배송은 정확하게."]'::jsonb,'[{"phrase": "Fresh beans → 갓 볶은 원두", "why": "원두에서 fresh는 ''갓 볶은''이 정확해요."}, {"phrase": "right on schedule → 약속한 날에 딱 맞춰", "why": "구독 서비스에서는 ''스케줄대로''보다 ''제때'', ''약속한 날''이 자연스러워요."}]'::jsonb),
('dr-20260929-ek-m3','몸은 더 늘리고, 스트레스는 덜고.','["몸은 활짝, 마음은 가볍게.", "더 펴고, 덜 쌓고."]'::jsonb,'[{"phrase": "more / less 대구", "why": "Stretch와 Stress의 두운(st-), more와 less의 대비가 핵심이에요. 한국어도 ''더/덜'' 짝을 맞춰 리듬을 살려요."}, {"phrase": "명령형 → 연결형", "why": "''더 스트레칭하라''는 딱딱해요. SNS 카피는 끝을 흐려 여운을 남겨요."}]'::jsonb),
('dr-20260929-ek-b1','보내기 전에 한번 봐 주실 수 있을까요?','["발송 전에 잠깐 검토 부탁드려도 될까요?", "내보내기 전에 가볍게 한번 확인해 주시겠어요?"]'::jsonb,'[{"phrase": "Would you mind ~ing → ~해 주실 수 있을까요", "why": "''~하는 것을 꺼리시나요''로 직역하지 않아요. 정중한 부탁이에요."}, {"phrase": "take a quick look → 한번 봐 주다", "why": "''빠른 봄''이 아니라 가볍게 확인해 달라는 말이에요."}]'::jsonb),
('dr-20260929-ek-b2','이달 말 출시 일정대로 순조롭게 진행 중입니다.','["월말 출시에 맞춰 잘 진행되고 있어요.", "예정대로 이달 안에 출시할 수 있을 것 같습니다."]'::jsonb,'[{"phrase": "on track → 순조롭게 진행 중", "why": "''트랙 위에 있다''가 아니라 계획대로 가고 있다는 뜻이에요."}, {"phrase": "by the end of the month → 이달 말까지", "why": "by는 ''~까지''예요."}]'::jsonb),
('dr-20260929-ek-b3','이보다 더 좋은 파트너는 없었을 거예요.','["함께해 주셔서 정말 든든했습니다.", "최고의 파트너와 일할 수 있어 감사했습니다."]'::jsonb,'[{"phrase": "couldn''t have asked for a better ~", "why": "''더 좋은 것을 요청할 수 없었다''가 아니라 ''이보다 좋을 수 없다''는 최고의 칭찬이에요."}, {"phrase": "격", "why": "비즈니스 감사 인사라 ''~했습니다''로 정중하게 끝내도 좋아요."}]'::jsonb),
('dr-20260929-ek-d1','나도 그랬어. 점점 나아져, 진짜야.','["나도 겪어 봤어. 갈수록 괜찮아질 거야, 약속해.", "그 마음 알아. 조금씩 나아질 거야, 믿어 봐."]'::jsonb,'[{"phrase": "I''ve been there → 나도 그랬어", "why": "''거기 가 봤다''가 아니라 같은 일을 겪어 봤다는 공감이에요."}, {"phrase": "I promise → 진짜야", "why": "문장 끝의 I promise는 ''진짜야''처럼 가볍게 옮겨요."}]'::jsonb),
('dr-20260929-ek-d2','천천히 와. 나 방금 커피 한 잔 샀어.','["서두르지 마. 커피 마시면서 기다리고 있어.", "급하게 안 와도 돼. 커피 한 잔 하고 있을게."]'::jsonb,'[{"phrase": "No rush → 천천히 와", "why": "''서두름 없음''이 아니라 급하지 않다는 배려예요."}, {"phrase": "grab a coffee → 커피 한 잔 사다", "why": "grab은 ''잡다''가 아니라 가볍게 사거나 먹는다는 구어예요."}]'::jsonb),
('dr-20260929-ek-d3','그만해, 부끄럽잖아.','["왜 이래, 얼굴 빨개지잖아.", "아 뭐야, 쑥스럽게."]'::jsonb,'[{"phrase": "Stop → 그만해, 왜 이래", "why": "진짜로 멈추라는 게 아니라 쑥스러워서 하는 말이에요."}, {"phrase": "making me blush → 부끄럽잖아", "why": "''얼굴을 붉게 만든다''보다 ''쑥스럽다, 부끄럽다''로 옮겨요."}]'::jsonb),
('dr-20260929-ek-t1','시드니행 902편 마지막 탑승 안내 말씀드립니다.','["시드니로 가는 902편 승객께서는 지금 바로 탑승해 주시기 바랍니다.", "902편 시드니행, 마지막 탑승 안내입니다."]'::jsonb,'[{"phrase": "final boarding call → 마지막 탑승 안내", "why": "공항 방송의 정해진 말이에요."}, {"phrase": "방송의 격", "why": "''~말씀드립니다'', ''~바랍니다''처럼 실제 방송 말투로 옮겨요."}]'::jsonb),
('dr-20260929-ek-t2','비행기 시간까지 짐을 맡아 드릴까요?','["출발 전까지 짐을 보관해 드릴까요?", "항공편 시간까지 가방을 맡아 드릴 수 있어요."]'::jsonb,'[{"phrase": "hold your luggage → 짐을 맡아 드리다", "why": "''짐을 들고 있다''가 아니라 보관해 준다는 뜻이에요."}, {"phrase": "Would you like us to → ~해 드릴까요", "why": "''우리가 ~하기를 원하세요''로 직역하지 않아요."}]'::jsonb),
('dr-20260929-ek-t3','참고로 주방이 20분 뒤에 마감돼요.','["미리 말씀드리면, 20분 후에 주문이 마감돼요.", "주방 마감이 20분 남았어요."]'::jsonb,'[{"phrase": "just so you know → 참고로", "why": "''당신이 알도록''이 아니라 부드럽게 알려 주는 말이에요."}, {"phrase": "kitchen closes → 주문 마감", "why": "식당에서는 ''라스트 오더'', ''주문 마감''과 같은 뜻이에요."}]'::jsonb);
